actions.script:
const basisTimestamp = new Date(ec.user.timestampMillis(ec.user.nowTimestamp) - daysToKeep * 86400000).toISOString()
let removed = 0
// read through the find's iterator, so a long log is not held whole; each row goes beside the cursor
const updates = ec.entity.find("moqui.resource.GitUpdate")
        .condition(ec.entity.conditionFactory.makeCondition("updateDate", "<", basisTimestamp))
        .disableAuthz().iterator()
try {
    for (const update of updates) {
        if (update.ecaStatus !== "done" && update.ecaStatus !== "none") continue
        try {
            ec.entity.find("moqui.resource.GitUpdateRef").condition("updateId", update.updateId).disableAuthz().deleteAll()
            ec.entity.find("moqui.resource.GitUpdate").condition("updateId", update.updateId).disableAuthz().deleteAll()
            removed++
        } catch (err) {
            ec.logger.log("error", "GitUpdate " + update.updateId + " was not removed: " + err)
        }
    }
} finally {
    updates.close()
}
recordsRemoved = removed

if (!access.canDelete) { ec.message.addError(ec.resource.expand('You may not change the branch rules of ${repositoryId}', '', {repositoryId})); return }
const methods = String(allowedMergeMethods || '').split(',').map((item) => item.trim()).filter((item) => item)
const known = ['GmmMerge', 'GmmSquash', 'GmmFastForward', 'GmmRebase']
const unknown = methods.filter((method) => !known.includes(method))
if (unknown.length) { ec.message.addError('Not merge methods: ' + unknown.join(', ')); return }
const yn = (value) => (value === true || value === 'Y' || value === 'true') ? 'Y' : 'N'
const fields = {repositoryId, refPattern: String(refPattern).trim(), allowForcePush: yn(allowForcePush),
    allowDelete: yn(allowDelete), requireMergeRequest: yn(requireMergeRequest),
    requiredApprovals: Math.max(0, requiredApprovals || 0), dismissStaleApprovals: yn(dismissStaleApprovals),
    requiredStatusContexts: requiredStatusContexts || null, allowedMergeMethods: methods.join(',') || null,
    pushUserGroupId: pushUserGroupId || null}
let rule = branchRuleId ? ec.entity.find('moqui.resource.GitBranchRule').condition('branchRuleId', branchRuleId).disableAuthz().one() : null
if (rule && rule.repositoryId !== repositoryId) { ec.message.addError('Branch rule ' + branchRuleId + ' is not of repository ' + repositoryId); return }
if (rule) {
    rule.setFields(fields, true, null, null)
    rule.update()
} else {
    rule = ec.entity.makeValue('moqui.resource.GitBranchRule')
    rule.setSequencedIdPrimary()
    rule.setFields(fields, true, null, null)
    rule.create()
}
branchRuleId = rule.branchRuleId

const rule = ec.entity.find('moqui.resource.GitBranchRule').condition('branchRuleId', branchRuleId).disableAuthz().one()
if (!rule) return
const access = ec.service.sync().name('org.moqui.git.GitServices.get#GitRepositoryAccess').parameters({repositoryId: rule.repositoryId}).call()
if (!access.canDelete) { ec.message.addError(ec.resource.expand('You may not change the branch rules of ${repositoryId}', '', {repositoryId: rule.repositoryId})); return }
rule.delete()

webhookList = []
if (!access.canDelete) { ec.message.addError(ec.resource.expand('You may not see the webhooks of ${repositoryId}', '', {repositoryId})); return }
for (const hook of Array.from(ec.entity.find('moqui.resource.GitWebhook').condition('repositoryId', repositoryId).orderBy('webhookId').disableAuthz().list())) {
    webhookList.push({webhookId: hook.webhookId, repositoryId: hook.repositoryId, url: hook.url, events: hook.events,
        active: hook.active, description: hook.description, hasSecret: !!hook.secret, createdDate: hook.createdDate,
        lastDeliveryDate: hook.lastDeliveryDate, lastDeliveryStatus: hook.lastDeliveryStatus})
}

if (!access.canDelete) { ec.message.addError(ec.resource.expand('You may not change the webhooks of ${repositoryId}', '', {repositoryId})); return }
const target = String(url).trim()
if (!/^https?:\/\/[^\s/]+/.test(target)) { ec.message.addError(ec.l10n.localize('A webhook URL is http or https')); return }
const known = ['push', 'tag', 'merge_request']
const list = String(events || '').split(',').map((item) => item.trim()).filter((item) => item)
const unknown = list.filter((item) => !known.includes(item))
if (unknown.length) { ec.message.addError('Not webhook events: ' + unknown.join(', ')); return }
const fields = {repositoryId, url: target, events: list.join(',') || null,
    active: (active === false || active === 'N' || active === 'false') ? 'N' : 'Y', description: description || null}
if (secret) fields.secret = secret
let hook = webhookId ? ec.entity.find('moqui.resource.GitWebhook').condition('webhookId', webhookId).disableAuthz().one() : null
if (hook && hook.repositoryId !== repositoryId) { ec.message.addError('Webhook ' + webhookId + ' is not of repository ' + repositoryId); return }
if (hook) {
    hook.setFields(fields, true, null, null)
    hook.update()
} else {
    hook = ec.entity.makeValue('moqui.resource.GitWebhook')
    hook.setSequencedIdPrimary()
    hook.setFields(fields, true, null, null)
    hook.createdByUserId = ec.user.userId
    hook.createdDate = ec.user.nowTimestamp
    hook.create()
}
webhookId = hook.webhookId

const hook = ec.entity.find('moqui.resource.GitWebhook').condition('webhookId', webhookId).disableAuthz().one()
if (!hook) return
const access = ec.service.sync().name('org.moqui.git.GitServices.get#GitRepositoryAccess').parameters({repositoryId: hook.repositoryId}).call()
if (!access.canDelete) { ec.message.addError(ec.resource.expand('You may not change the webhooks of ${repositoryId}', '', {repositoryId: hook.repositoryId})); return }
ec.entity.find('moqui.service.message.SystemMessage').condition({systemMessageTypeId: 'GitWebhook', receiverId: webhookId, statusId: 'SmsgProduced'})
        .disableAuthz().updateAll({statusId: 'SmsgCancelled'})
hook.delete()

parameter.description:
Maps: systemMessageId, event, statusId (SmsgProduced
                while it is retried, SmsgSent, SmsgError when it gave up, SmsgCancelled), initDate, lastAttemptDate,
                processedDate, failCount, httpStatus, messageText, errorList (errorDate, errorText)

actions.script:
deliveryList = []
deliveryListCount = 0
const hook = ec.entity.find('moqui.resource.GitWebhook').condition('webhookId', webhookId).disableAuthz().one()
if (!hook) { ec.message.addError('No webhook ' + webhookId); return }
const access = ec.service.sync().name('org.moqui.git.GitServices.get#GitRepositoryAccess').parameters({repositoryId: hook.repositoryId}).call()
if (!access.canDelete) { ec.message.addError(ec.resource.expand('You may not see the webhooks of ${repositoryId}', '', {repositoryId: hook.repositoryId})); return }
const find = () => ec.entity.find('moqui.service.message.SystemMessage').condition({systemMessageTypeId: 'GitWebhook', receiverId: webhookId}).disableAuthz()
deliveryListCount = find().count()
const messages = Array.from(find().orderBy('-initDate').orderBy('-systemMessageId').offset(pageIndex * pageSize).limit(pageSize).list())
for (const message of messages) {
    const errors = Array.from(ec.entity.find('moqui.service.message.SystemMessageError').condition('systemMessageId', message.systemMessageId)
            .orderBy('-errorDate').disableAuthz().list()).map((error) => ({errorDate: error.errorDate, errorText: error.errorText}))
    deliveryList.push({systemMessageId: message.systemMessageId, event: message.docType, statusId: message.statusId,
        initDate: message.initDate, lastAttemptDate: message.lastAttemptDate, processedDate: message.processedDate,
        failCount: message.failCount || 0, httpStatus: message.remoteMessageId, messageText: message.messageText, errorList: errors})
}

retriedCount = 0
const now = ec.user.timestampMillis(ec.user.nowTimestamp)
const pending = Array.from(ec.entity.find('moqui.service.message.SystemMessage')
        .condition({systemMessageTypeId: 'GitWebhook', statusId: 'SmsgProduced', isOutgoing: 'Y'})
        .orderBy('initDate').limit(200).disableAuthz().list())
for (const message of pending) {
    const failures = message.failCount || 0
    if (failures === 0 && message.lastAttemptDate == null && now - ec.user.timestampMillis(message.initDate) < 60000) continue
    if (failures >= retryLimit) {
        ec.entity.find('moqui.service.message.SystemMessage').condition('systemMessageId', message.systemMessageId).disableAuthz()
                .updateAll({statusId: 'SmsgError'})
        continue
    }
    const last = message.lastAttemptDate ? ec.user.timestampMillis(message.lastAttemptDate) : 0
    if (now - last < Math.pow(2, failures) * 60000) continue
    try {
        ec.service.sync().name('org.moqui.impl.SystemMessageServices.send#ProducedSystemMessage')
                .parameters({systemMessageId: message.systemMessageId}).call()
        retriedCount++
    } catch (err) {
        ec.logger.log('error', 'Webhook delivery ' + message.systemMessageId + ' not retried: ' + err)
    }
    ec.message.clearErrors()
}
